from collections import Counter
from typing import List

def numDuplicates(name: List[str], price: List[int], weight: List[int]) -> int:
    cnt = Counter(zip(name, price, weight))
    return sum(c - 1 for c in cnt.values())

import java.util.*;

class Solution {
    int numDuplicates(List<String> name, List<Integer> price, List<Integer> weight) {
        Map<String, Integer> cnt = new HashMap<>();
        int dup = 0;
        for (int i = 0; i < name.size(); i++) {
            String key = name.get(i) + "|" + price.get(i) + "|" + weight.get(i);
            int c = cnt.merge(key, 1, Integer::sum);
            if (c > 1) dup++;          // 第二次及以后出现都算一个重复
        }
        return dup;
    }
}
